<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { api, errorMessage } from '../api';
type Customer={_id:string;name:string;email:string;phone:string}; type Vehicle={_id:string;plate:string;brand:string;model:string;year:number;customerId?:Customer};
const customers=ref<Customer[]>([]), vehicles=ref<Vehicle[]>([]), error=ref(''), saved=ref(''); const customerDialog=ref(false), vehicleDialog=ref(false); const customer=ref({name:'',email:'',phone:''}), vehicle=ref({customerId:'',plate:'',brand:'',model:'',year:new Date().getFullYear(),vin:'',color:''});
async function load(){try{[customers.value,vehicles.value]=(await Promise.all([api.get('/customers'),api.get('/vehicles')])).map(r=>r.data)}catch(e){error.value=errorMessage(e)}} onMounted(load);
async function saveCustomer(){try{await api.post('/customers',customer.value); customerDialog.value=false; customer.value={name:'',email:'',phone:''}; saved.value='Cliente creado'; await load()}catch(e){error.value=errorMessage(e)}}
async function saveVehicle(){try{await api.post('/vehicles',vehicle.value); vehicleDialog.value=false; saved.value='Vehículo registrado'; await load()}catch(e){error.value=errorMessage(e)}}
</script>
<template><div class="d-flex align-center mb-5"><h1 class="text-h4">Clientes y vehículos</h1><v-spacer/><v-btn color="primary" class="mr-2" @click="customerDialog=true">Nuevo cliente</v-btn><v-btn color="secondary" @click="vehicleDialog=true">Nuevo vehículo</v-btn></div><v-alert v-if="error" type="error" closable @click:close="error=''">{{error}}</v-alert><v-alert v-if="saved" type="success" closable @click:close="saved=''">{{saved}}</v-alert><v-row class="mt-2"><v-col cols="12" md="5"><v-card title="Clientes"><v-list><v-list-item v-for="c in customers" :key="c._id" :title="c.name" :subtitle="`${c.email} · ${c.phone}`"/></v-list></v-card></v-col><v-col cols="12" md="7"><v-card title="Vehículos"><v-table><thead><tr><th>Placa</th><th>Vehículo</th><th>Cliente</th></tr></thead><tbody><tr v-for="v in vehicles" :key="v._id"><td>{{v.plate}}</td><td>{{v.brand}} {{v.model}} {{v.year}}</td><td>{{v.customerId?.name || '—'}}</td></tr></tbody></v-table></v-card></v-col></v-row>
<v-dialog v-model="customerDialog" max-width="500"><v-card title="Nuevo cliente"><v-card-text><v-text-field v-model="customer.name" label="Nombre"/><v-text-field v-model="customer.email" label="Correo"/><v-text-field v-model="customer.phone" label="Teléfono"/></v-card-text><v-card-actions><v-spacer/><v-btn @click="customerDialog=false">Cancelar</v-btn><v-btn color="primary" @click="saveCustomer">Guardar</v-btn></v-card-actions></v-card></v-dialog>
<v-dialog v-model="vehicleDialog" max-width="550"><v-card title="Nuevo vehículo"><v-card-text><v-select v-model="vehicle.customerId" label="Cliente" :items="customers" item-title="name" item-value="_id"/><v-text-field v-model="vehicle.plate" label="Placa"/><v-row><v-col><v-text-field v-model="vehicle.brand" label="Marca"/></v-col><v-col><v-text-field v-model="vehicle.model" label="Modelo"/></v-col></v-row><v-text-field v-model.number="vehicle.year" label="Año" type="number"/></v-card-text><v-card-actions><v-spacer/><v-btn @click="vehicleDialog=false">Cancelar</v-btn><v-btn color="primary" @click="saveVehicle">Guardar</v-btn></v-card-actions></v-card></v-dialog></template>
